  3	import com.pousadamarealta.api.ReservationController;
  4	import com.pousadamarealta.repository.*;
  5	import com.pousadamarealta.service.PricingService;
  6	import com.pousadamarealta.service.ReportService;
  7	import com.pousadamarealta.service.ReservationService;
  8	import com.zaxxer.hikari.HikariConfig;
  9	import com.zaxxer.hikari.HikariDataSource;
 10	import io.javalin.Javalin;
 11	
 12	import javax.sql.DataSource;
 13	
 14	public class App {
 15	    public static void main(String[] args) {
 16	        String dbUrl = getEnv("DB_URL", null);
 17	        String dbUser = getEnv("DB_USER", null);
 18	        String dbPassword = getEnv("DB_PASSWORD", null);
 19	        int port = Integer.parseInt(getEnv("PORT", "7070"));
 20	
 21	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 22	            throw new IllegalStateException("Database configuration is required: DB_URL, DB_USER, DB_PASSWORD");
 23	        }
 24	
 25	        DataSource dataSource = createDataSource(dbUrl, dbUser, dbPassword);
 26	
 27	        DatabaseInitializer dbInitializer = new DatabaseInitializer(dataSource);
 28	        dbInitializer.initialize();
 29	
 30	        RoomRepository roomRepository = new JdbcRoomRepository(dataSource);
 31	        roomRepository.initialize();
 32	
 33	        ReservationRepository reservationRepository = new JdbcReservationRepository(dataSource);
 34	        MessageRepository messageRepository = new JdbcMessageRepository(dataSource);
 35	
 36	        PricingService pricingService = new PricingService();
 37	        ReservationService reservationService = new ReservationService(
 38	            reservationRepository, roomRepository, messageRepository, pricingService);
 39	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 40	
 41	        ReservationController controller = new ReservationController(
 42	            reservationService, reportService, roomRepository, messageRepository);
 43	
 44	        Javalin app = Javalin.create(config -> {
 45	            config.http.defaultContentType = "application/json";
 46	        }).start(port);
 47	
 48	        app.get("/rooms", controller::getRooms);
 49	        app.post("/reservations", controller::createReservation);
 50	        app.get("/reservations/{id}", controller::getReservation);
 51	        app.post("/reservations/{id}/confirmation", controller::confirmReservation);
 52	        app.post("/reservations/{id}/cancellation", controller::cancelReservation);
 53	        app.post("/reservations/{id}/check-in", controller::checkIn);
 54	        app.post("/reservations/{id}/check-out", controller::checkOut);
 55	        app.get("/reservations/{id}/document", controller::getDocument);
 56	        app.get("/messages", controller::getMessages);
 57	        app.get("/reports/occupancy", controller::getOccupancyReport);
 58	        app.get("/reports/revenue", controller::getRevenueReport);
 59	        app.get("/reports/tourism-tax", controller::getTourismTaxReport);
 60	        app.get("/reports/rate-plans", controller::getRatePlansReport);
 61	
 62	        System.out.println("Pousada Maré Alta - Sistema de Reservas");
 63	        System.out.println("Servidor iniciado na porta " + port);
 64	    }
 65	
 66	    private static DataSource createDataSource(String url, String user, String password) {
 67	        HikariConfig config = new HikariConfig();
 68	        config.setJdbcUrl(url);
 69	        config.setUsername(user);
 70	        config.setPassword(password);
 71	        config.setMaximumPoolSize(10);
 72	        return new HikariDataSource(config);
 73	    }
 74	
 75	    private static String getEnv(String name, String defaultValue) {
 76	        String value = System.getenv(name);
 77	        return value != null ? value : defaultValue;
 78	    }
 79	}
 80	package com.pousadamarealta.api;
 81	
 82	import com.fasterxml.jackson.databind.ObjectMapper;
 83	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 84	import com.pousadamarealta.domain.*;
 85	import com.pousadamarealta.repository.MessageRepository;
 86	import com.pousadamarealta.repository.RoomRepository;
 87	import com.pousadamarealta.service.*;
 88	import io.javalin.http.Context;
 89	
 90	import java.time.LocalDate;
 91	import java.time.YearMonth;
 92	import java.time.format.DateTimeParseException;
 93	import java.util.HashMap;
 94	import java.util.List;
 95	import java.util.Map;
 96	
 97	public class ReservationController {
 98	    private final ReservationService reservationService;
 99	    private final ReportService reportService;
100	    private final RoomRepository roomRepository;
101	    private final MessageRepository messageRepository;
102	    private final ObjectMapper objectMapper;
103	
104	    public ReservationController(ReservationService reservationService,
105	                                ReportService reportService,
106	                                RoomRepository roomRepository,
107	                                MessageRepository messageRepository) {
108	        this.reservationService = reservationService;
109	        this.reportService = reportService;
110	        this.roomRepository = roomRepository;
111	        this.messageRepository = messageRepository;
112	        this.objectMapper = new ObjectMapper();
113	        this.objectMapper.registerModule(new JavaTimeModule());
114	    }
115	
116	    public void getRooms(Context ctx) {
117	        List<Room> rooms = roomRepository.findAll();
118	        List<Map<String, Object>> response = rooms.stream()
119	            .map(room -> {
120	                Map<String, Object> map = new HashMap<>();
121	                map.put("number", room.getNumber());
122	                map.put("type", room.getType().name());
123	                map.put("capacity", room.getCapacity());
124	                map.put("nightlyRate", room.getNightlyRate());
125	                return map;
126	            })
127	            .toList();
128	        ctx.json(response);
129	    }
130	
131	    public void createReservation(Context ctx) {
132	        try {
133	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
134	
135	            validateRequiredField(request.getRoomNumber(), "roomNumber");
136	            validateRequiredField(request.getGuestName(), "guestName");
137	            validateRequiredField(request.getGuestEmail(), "guestEmail");
138	            validateRequiredField(request.getGuestCpf(), "guestCpf");
139	            validateRequiredField(request.getCheckIn(), "checkIn");
140	            validateRequiredField(request.getCheckOut(), "checkOut");
141	            validateRequiredField(request.getGuests(), "guests");
142	            validateRequiredField(request.getRatePlan(), "ratePlan");
143	
144	            LocalDate checkIn = parseDate(request.getCheckIn());
145	            LocalDate checkOut = parseDate(request.getCheckOut());
146	            RatePlan ratePlan = parseRatePlan(request.getRatePlan());
147	
148	            Reservation reservation = reservationService.createReservation(
149	                request.getRoomNumber(),
150	                request.getGuestName(),
151	                request.getGuestEmail(),
152	                request.getGuestCpf(),
153	                checkIn,
154	                checkOut,
155	                request.getGuests(),
156	                ratePlan
157	            );
158	
159	            ctx.status(201).json(toMap(reservation));
160	        } catch (InvalidRequestException e) {
161	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
162	        } catch (RoomNotFoundException e) {
163	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
164	        } catch (RoomUnavailableException e) {
165	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
166	        } catch (CapacityExceededException e) {
167	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
168	        }
169	    }
170	
171	    public void getReservation(Context ctx) {
172	        try {
173	            Long id = Long.parseLong(ctx.pathParam("id"));
174	            Reservation reservation = reservationService.getReservation(id);
175	            ctx.json(toMap(reservation));
176	        } catch (ReservationNotFoundException e) {
177	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
178	        }
179	    }
180	
181	    public void confirmReservation(Context ctx) {
182	        try {
183	            Long id = Long.parseLong(ctx.pathParam("id"));
184	            Reservation reservation = reservationService.confirmReservation(id);
185	            ctx.json(toMap(reservation));
186	        } catch (ReservationNotFoundException e) {
187	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
188	        } catch (OperationNotAllowedException e) {
189	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
190	        }
191	    }
192	
193	    public void cancelReservation(Context ctx) {
194	        try {
195	            Long id = Long.parseLong(ctx.pathParam("id"));
196	            Reservation reservation = reservationService.cancelReservation(id);
197	            ctx.json(toMap(reservation));
198	        } catch (ReservationNotFoundException e) {
199	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
200	        } catch (OperationNotAllowedException e) {
201	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
202	        }
203	    }
204	
205	    public void checkIn(Context ctx) {
206	        try {
207	            Long id = Long.parseLong(ctx.pathParam("id"));
208	            Reservation reservation = reservationService.checkIn(id);
209	            ctx.json(toMap(reservation));
210	        } catch (ReservationNotFoundException e) {
211	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
212	        } catch (OperationNotAllowedException e) {
213	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
214	        }
215	    }
216	
217	    public void checkOut(Context ctx) {
218	        try {
219	            Long id = Long.parseLong(ctx.pathParam("id"));
220	            Reservation reservation = reservationService.checkOut(id);
221	            String document = reservationService.generateDocument(reservation);
222	            ctx.json(toDocumentMap(reservation, document));
223	        } catch (ReservationNotFoundException e) {
224	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
225	        } catch (OperationNotAllowedException e) {
226	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
227	        }
228	    }
229	
230	    public void getDocument(Context ctx) {
231	        try {
232	            Long id = Long.parseLong(ctx.pathParam("id"));
233	            Reservation reservation = reservationService.getReservation(id);
234	            String document = reservationService.generateDocument(reservation);
235	            ctx.json(toDocumentMap(reservation, document));
236	        } catch (ReservationNotFoundException e) {
237	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
238	        } catch (OperationNotAllowedException e) {
239	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
240	        }
241	    }
242	
243	    public void getMessages(Context ctx) {
244	        List<Message> messages = messageRepository.findAll();
245	        ctx.json(messages);
246	    }
247	
248	    public void getOccupancyReport(Context ctx) {
249	        try {
250	            String dateParam = ctx.queryParam("date");
251	            if (dateParam == null || dateParam.isEmpty()) {
252	                throw new InvalidRequestException("date parameter is required");
253	            }
254	            LocalDate date = parseDate(dateParam);
255	            String csv = reportService.generateOccupancyReport(date);
256	            ctx.contentType("text/csv; charset=utf-8").result(csv);
257	        } catch (InvalidRequestException e) {
258	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
259	        }
260	    }
261	
262	    public void getRevenueReport(Context ctx) {
263	        try {
264	            String monthParam = ctx.queryParam("month");
265	            if (monthParam == null || monthParam.isEmpty()) {
266	                throw new InvalidRequestException("month parameter is required");
267	            }
268	            YearMonth month = parseMonth(monthParam);
269	            String csv = reportService.generateRevenueReport(month);
270	            ctx.contentType("text/csv; charset=utf-8").result(csv);
271	        } catch (InvalidRequestException e) {
272	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
273	        }
274	    }
275	
276	    public void getTourismTaxReport(Context ctx) {
277	        try {
278	            String monthParam = ctx.queryParam("month");
279	            if (monthParam == null || monthParam.isEmpty()) {
280	                throw new InvalidRequestException("month parameter is required");
281	            }
282	            YearMonth month = parseMonth(monthParam);
283	            String csv = reportService.generateTourismTaxReport(month);
284	            ctx.contentType("text/csv; charset=utf-8").result(csv);
285	        } catch (InvalidRequestException e) {
286	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
287	        }
288	    }
289	
290	    public void getRatePlansReport(Context ctx) {
291	        try {
292	            String monthParam = ctx.queryParam("month");
293	            if (monthParam == null || monthParam.isEmpty()) {
294	                throw new InvalidRequestException("month parameter is required");
295	            }
296	            YearMonth month = parseMonth(monthParam);
297	            String csv = reportService.generateRatePlansReport(month);
298	            ctx.contentType("text/csv; charset=utf-8").result(csv);
299	        } catch (InvalidRequestException e) {
300	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
301	        }
302	    }
303	
304	    private void validateRequiredField(Object value, String fieldName) {
305	        if (value == null) {
306	            throw new InvalidRequestException("Missing required field: " + fieldName);
307	        }
308	        if (value instanceof String && ((String) value).isEmpty()) {
309	            throw new InvalidRequestException("Missing required field: " + fieldName);
310	        }
311	    }
312	
313	    private LocalDate parseDate(String date) {
314	        try {
315	            return LocalDate.parse(date);
316	        } catch (DateTimeParseException e) {
317	            throw new InvalidRequestException("Invalid date format: " + date);
318	        }
319	    }
320	
321	    private YearMonth parseMonth(String month) {
322	        try {
323	            return YearMonth.parse(month);
324	        } catch (DateTimeParseException e) {
325	            throw new InvalidRequestException("Invalid month format: " + month);
326	        }
327	    }
328	
329	    private RatePlan parseRatePlan(String ratePlan) {
330	        try {
331	            return RatePlan.valueOf(ratePlan);
332	        } catch (IllegalArgumentException e) {
333	            throw new InvalidRequestException("Invalid rate plan: " + ratePlan);
334	        }
335	    }
336	
337	    private Map<String, Object> toMap(Reservation reservation) {
338	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
339	
340	        Map<String, Object> map = new HashMap<>();
341	        map.put("id", reservation.getId());
342	        map.put("roomNumber", reservation.getRoomNumber());
343	        map.put("guestName", reservation.getGuestName());
344	        map.put("guestEmail", reservation.getGuestEmail());
345	        map.put("guestCpf", reservation.getGuestCpf());
346	        map.put("checkIn", reservation.getCheckIn().toString());
347	        map.put("checkOut", reservation.getCheckOut().toString());
348	        map.put("guests", reservation.getGuests());
349	        map.put("ratePlan", reservation.getRatePlan().name());
350	        map.put("nights", reservation.getNights());
351	        map.put("subtotal", reservation.getSubtotal());
352	        map.put("discount", reservation.getDiscount());
353	        map.put("total", reservation.getTotal());
354	        map.put("status", reservation.getStatus().name());
355	        map.put("amountPaid", reservation.getAmountPaid());
356	        map.put("refund", reservation.getRefund());
357	        return map;
358	    }
359	
360	    private Map<String, Object> toDocumentMap(Reservation reservation, String document) {
361	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
362	
363	        Map<String, Object> map = new HashMap<>();
364	        map.put("title", "Comprovante de reserva");
365	        map.put("reservationId", reservation.getId());
366	        map.put("guestName", reservation.getGuestName());
367	        map.put("guestCpf", reservation.getGuestCpf());
368	        map.put("roomNumber", reservation.getRoomNumber());
369	        map.put("roomType", room.getType().name());
370	        map.put("checkIn", reservation.getCheckIn().toString());
371	        map.put("checkOut", reservation.getCheckOut().toString());
372	        map.put("nights", reservation.getNights());
373	        map.put("subtotal", reservation.getSubtotal());
374	        map.put("discount", reservation.getDiscount());
375	        map.put("total", reservation.getTotal());
376	        return map;
377	    }
378	}

