  8	import java.math.BigDecimal;
  9	import java.time.LocalDate;
 10	import java.time.temporal.ChronoUnit;
 11	import java.util.List;
 12	
 13	public class ReservationService {
 14	    private final ReservationRepository reservationRepository;
 15	    private final RoomRepository roomRepository;
 16	    private final MessageRepository messageRepository;
 17	    private final PricingService pricingService;
 18	
 19	    public ReservationService(ReservationRepository reservationRepository,
 20	                            RoomRepository roomRepository,
 21	                            MessageRepository messageRepository,
 22	                            PricingService pricingService) {
 23	        this.reservationRepository = reservationRepository;
 24	        this.roomRepository = roomRepository;
 25	        this.messageRepository = messageRepository;
 26	        this.pricingService = pricingService;
 27	    }
 28	
 29	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
 30	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
 31	                                        int guests, RatePlan ratePlan) {
 32	        Room room = roomRepository.findByNumber(roomNumber)
 33	                .orElseThrow(() -> new RoomNotFoundException(roomNumber));
 34	
 35	        if (guests < 1) {
 36	            throw new InvalidRequestException("Number of guests must be at least 1");
 37	        }
 38	
 39	        if (guests > room.getCapacity()) {
 40	            throw new CapacityExceededException(guests, room.getCapacity());
 41	        }
 42	
 43	        if (!checkOut.isAfter(checkIn)) {
 44	            throw new InvalidRequestException("Check-out must be after check-in");
 45	        }
 46	
 47	        if (!isRoomAvailable(roomNumber, checkIn, checkOut, null)) {
 48	            throw new RoomUnavailableException(roomNumber);
 49	        }
 50	
 51	        Reservation reservation = new Reservation();
 52	        reservation.setRoomNumber(roomNumber);
 53	        reservation.setGuestName(guestName);
 54	        reservation.setGuestEmail(guestEmail);
 55	        reservation.setGuestCpf(guestCpf);
 56	        reservation.setCheckIn(checkIn);
 57	        reservation.setCheckOut(checkOut);
 58	        reservation.setGuests(guests);
 59	        reservation.setRatePlan(ratePlan);
 60	
 61	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
 62	        reservation.setNights(nights);
 63	
 64	        BigDecimal subtotal = pricingService.calculateSubtotal(room, checkIn, checkOut);
 65	        reservation.setSubtotal(subtotal);
 66	
 67	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
 68	        reservation.setDiscount(discount);
 69	
 70	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
 71	        reservation.setTotal(total);
 72	
 73	        return reservationRepository.save(reservation);
 74	    }
 75	
 76	    public Reservation getReservation(Long id) {
 77	        return reservationRepository.findById(id)
 78	                .orElseThrow(() -> new ReservationNotFoundException(id));
 79	    }
 80	
 81	    public Reservation confirmReservation(Long id) {
 82	        Reservation reservation = getReservation(id);
 83	
 84	        if (reservation.getStatus() != ReservationStatus.PENDING) {
 85	            throw new OperationNotAllowedException("Cannot confirm reservation in status " + reservation.getStatus());
 86	        }
 87	
 88	        reservation.setStatus(ReservationStatus.CONFIRMED);
 89	        reservation.setAmountPaid(reservation.getTotal());
 90	        reservationRepository.update(reservation);
 91	
 92	        sendConfirmationEmail(reservation);
 93	
 94	        return reservation;
 95	    }
 96	
 97	    public Reservation cancelReservation(Long id) {
 98	        Reservation reservation = getReservation(id);
 99	
100	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN
101	            || reservation.getStatus() == ReservationStatus.CHECKED_OUT) {
102	            throw new OperationNotAllowedException("Cannot cancel reservation in status " + reservation.getStatus());
103	        }
104	
105	        if (reservation.getStatus() == ReservationStatus.CANCELLED) {
106	            throw new OperationNotAllowedException("Reservation is already cancelled");
107	        }
108	
109	        BigDecimal refundAmount = calculateRefund(reservation);
110	
111	        reservation.setStatus(ReservationStatus.CANCELLED);
112	        reservation.setRefund(refundAmount);
113	        reservationRepository.update(reservation);
114	
115	        return reservation;
116	    }
117	
118	    public Reservation checkIn(Long id) {
119	        Reservation reservation = getReservation(id);
120	
121	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
122	            throw new OperationNotAllowedException("Cannot check-in reservation in status " + reservation.getStatus());
123	        }
124	
125	        reservation.setStatus(ReservationStatus.CHECKED_IN);
126	        reservationRepository.update(reservation);
127	
128	        return reservation;
129	    }
130	
131	    public Reservation checkOut(Long id) {
132	        Reservation reservation = getReservation(id);
133	
134	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
135	            throw new OperationNotAllowedException("Cannot check-out reservation in status " + reservation.getStatus());
136	        }
137	
138	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
139	        reservationRepository.update(reservation);
140	
141	        return reservation;
142	    }
143	
144	    private BigDecimal calculateRefund(Reservation reservation) {
145	        if (reservation.getRatePlan() == RatePlan.NON_REFUNDABLE) {
146	            return BigDecimal.ZERO;
147	        }
148	        return reservation.getAmountPaid();
149	    }
150	
151	    private void sendConfirmationEmail(Reservation reservation) {
152	        String document = generateDocument(reservation);
153	        String body = String.format("Olá, %s!\n\n" +
154	                "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
155	                "%s\n\n" +
156	                "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
157	                "Até breve!", reservation.getGuestName(), document);
158	
159	        Message message = new Message("EMAIL", reservation.getGuestEmail(),
160	                "Reserva confirmada - Pousada Maré Alta", body);
161	        messageRepository.save(message);
162	    }
163	
164	    public String generateDocument(Reservation reservation) {
165	        if (!reservation.isPaid()) {
166	            throw new OperationNotAllowedException("Document is only available for paid reservations");
167	        }
168	
169	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
170	
171	        StringBuilder doc = new StringBuilder();
172	        doc.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
173	        doc.append("Hóspede: ").append(reservation.getGuestName())
174	           .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
175	        doc.append("Quarto: ").append(reservation.getRoomNumber())
176	           .append(" (").append(room.getType()).append(")\n");
177	        doc.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
178	           .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
179	           .append(" | ").append(reservation.getNights())
180	           .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
181	        doc.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
182	
183	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
184	            doc.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
185	        }
186	
187	        doc.append("Total: ").append(formatMoney(reservation.getTotal()));
188	
189	        return doc.toString();
190	    }
191	
192	    private boolean isRoomAvailable(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeReservationId) {
193	        List<Reservation> conflicting = reservationRepository.findConflicting(roomNumber, checkIn, checkOut);
194	
195	        if (excludeReservationId != null) {
196	            conflicting.removeIf(r -> r.getId().equals(excludeReservationId));
197	        }
198	
199	        return conflicting.isEmpty();
200	    }
201	
202	    private String formatCpf(String cpf) {
203	        if (cpf.length() == 11) {
204	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "."
205	                 + cpf.substring(6, 9) + "-" + cpf.substring(9, 11);
206	        }
207	        return cpf;
208	    }
209	
210	    private String formatDate(LocalDate date) {
211	        return String.format("%02d/%02d/%04d",
212	            date.getDayOfMonth(), date.getMonthValue(), date.getYear());
213	    }
214	
215	    private String formatMoney(BigDecimal amount) {
216	        return String.format("R$ %,.2f", amount).replace(",", "X").replace(".", ",").replace("X", ".");
217	    }
218	}
219	package com.pousadamarealta.service;
220	
221	import com.pousadamarealta.domain.RatePlan;
222	import com.pousadamarealta.domain.Reservation;
223	import com.pousadamarealta.domain.ReservationStatus;
224	import com.pousadamarealta.domain.Room;
225	import com.pousadamarealta.repository.ReservationRepository;
226	import com.pousadamarealta.repository.RoomRepository;
227	
228	import java.math.BigDecimal;
229	import java.math.RoundingMode;
230	import java.time.LocalDate;
231	import java.time.YearMonth;
232	import java.util.List;
233	import java.util.Map;
234	import java.util.stream.Collectors;
235	
236	public class ReportService {
237	    private static final String POUSADA_NAME = "Pousada Maré Alta";
238	    private static final BigDecimal TOURISM_TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
239	
240	    private final ReservationRepository reservationRepository;
241	    private final RoomRepository roomRepository;
242	
243	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
244	        this.reservationRepository = reservationRepository;
245	        this.roomRepository = roomRepository;
246	    }
247	
248	    public String generateOccupancyReport(LocalDate date) {
249	        List<Reservation> reservations = reservationRepository.findPaidByNight(date);
250	        int totalRooms = roomRepository.findAll().size();
251	
252	        StringBuilder csv = new StringBuilder();
253	        csv.append(formatTitle("occupancy", date.toString())).append("\n");
254	        csv.append("room,type,reservation,check_in,check_out\n");
255	
256	        for (Reservation reservation : reservations) {
257	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
258	            csv.append(reservation.getRoomNumber()).append(",")
259	               .append(room.getType()).append(",")
260	               .append(reservation.getId()).append(",")
261	               .append(reservation.getCheckIn()).append(",")
262	               .append(reservation.getCheckOut()).append("\n");
263	        }
264	
265	        csv.append("total,").append(reservations.size()).append("/").append(totalRooms);
266	
267	        return csv.toString();
268	    }
269	
270	    public String generateRevenueReport(YearMonth month) {
271	        List<Reservation> reservations = reservationRepository.findByMonth(month);
272	
273	        StringBuilder csv = new StringBuilder();
274	        csv.append(formatTitle("revenue", month.toString())).append("\n");
275	        csv.append("reservation,room,check_in,check_out,status,amount\n");
276	
277	        BigDecimal total = BigDecimal.ZERO;
278	
279	        for (Reservation reservation : reservations) {
280	            BigDecimal netAmount = calculateNetAmount(reservation);
281	
282	            if (netAmount.compareTo(BigDecimal.ZERO) > 0) {
283	                csv.append(reservation.getId()).append(",")
284	                   .append(reservation.getRoomNumber()).append(",")
285	                   .append(reservation.getCheckIn()).append(",")
286	                   .append(reservation.getCheckOut()).append(",")
287	                   .append(reservation.getStatus()).append(",")
288	                   .append(formatCsvMoney(netAmount)).append("\n");
289	
290	                total = total.add(netAmount);
291	            }
292	        }
293	
294	        csv.append("total,").append(formatCsvMoney(total));
295	
296	        return csv.toString();
297	    }
298	
299	    public String generateTourismTaxReport(YearMonth month) {
300	        List<Reservation> reservations = reservationRepository.findByMonth(month);
301	
302	        StringBuilder csv = new StringBuilder();
303	        csv.append(formatTitle("tourism-tax", month.toString())).append("\n");
304	        csv.append("reservation,room,check_in,check_out,guests,nights,tax\n");
305	
306	        BigDecimal total = BigDecimal.ZERO;
307	
308	        for (Reservation reservation : reservations) {
309	            if (isPaidReservation(reservation)) {
310	                BigDecimal tax = calculateTourismTax(reservation);
311	
312	                csv.append(reservation.getId()).append(",")
313	                   .append(reservation.getRoomNumber()).append(",")
314	                   .append(reservation.getCheckIn()).append(",")
315	                   .append(reservation.getCheckOut()).append(",")
316	                   .append(reservation.getGuests()).append(",")
317	                   .append(reservation.getNights()).append(",")
318	                   .append(formatCsvMoney(tax)).append("\n");
319	
320	                total = total.add(tax);
321	            }
322	        }
323	
324	        csv.append("total,").append(formatCsvMoney(total));
325	
326	        return csv.toString();
327	    }
328	
329	    public String generateRatePlansReport(YearMonth month) {
330	        List<Reservation> reservations = reservationRepository.findByMonth(month);
331	
332	        Map<RatePlan, List<Reservation>> byRatePlan = reservations.stream()
333	            .filter(r -> calculateNetAmount(r).compareTo(BigDecimal.ZERO) > 0)
334	            .collect(Collectors.groupingBy(Reservation::getRatePlan));
335	
336	        StringBuilder csv = new StringBuilder();
337	        csv.append(formatTitle("rate-plans", month.toString())).append("\n");
338	        csv.append("rate_plan,reservations,amount\n");
339	
340	        int totalCount = 0;
341	        BigDecimal totalAmount = BigDecimal.ZERO;
342	
343	        for (RatePlan ratePlan : RatePlan.values()) {
344	            List<Reservation> planReservations = byRatePlan.getOrDefault(ratePlan, List.of());
345	            int count = planReservations.size();
346	            BigDecimal amount = planReservations.stream()
347	                .map(this::calculateNetAmount)
348	                .reduce(BigDecimal.ZERO, BigDecimal::add);
349	
350	            csv.append(ratePlan).append(",")
351	               .append(count).append(",")
352	               .append(formatCsvMoney(amount)).append("\n");
353	
354	            totalCount += count;
355	            totalAmount = totalAmount.add(amount);
356	        }
357	
358	        csv.append("total,").append(totalCount).append(",").append(formatCsvMoney(totalAmount));
359	
360	        return csv.toString();
361	    }
362	
363	    private BigDecimal calculateNetAmount(Reservation reservation) {
364	        BigDecimal paid = reservation.getAmountPaid();
365	        BigDecimal refund = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
366	        return paid.subtract(refund);
367	    }
368	
369	    private boolean isPaidReservation(Reservation reservation) {
370	        return reservation.getStatus() == ReservationStatus.CONFIRMED
371	            || reservation.getStatus() == ReservationStatus.CHECKED_IN
372	            || reservation.getStatus() == ReservationStatus.CHECKED_OUT;
373	    }
374	
375	    private BigDecimal calculateTourismTax(Reservation reservation) {
376	        int guestNights = reservation.getGuests() * reservation.getNights();
377	        return TOURISM_TAX_PER_GUEST_PER_NIGHT.multiply(new BigDecimal(guestNights))
378	            .setScale(2, RoundingMode.HALF_EVEN);
379	    }
380	
381	    private String formatTitle(String reportName, String period) {
382	        return POUSADA_NAME + "," + reportName + "," + period;
383	    }
384	
385	    private String formatCsvMoney(BigDecimal amount) {
386	        return amount.setScale(2, RoundingMode.HALF_EVEN).toString();
387	    }
388	}
389	package com.pousadamarealta.service;
390	
391	import com.pousadamarealta.domain.RatePlan;
392	import com.pousadamarealta.domain.Room;
