 81	    public Reservation confirmReservation(Long id) {
 82	        Reservation reservation = getReservation(id);
 83	
 84	        if (reservation.getStatus() != ReservationStatus.PENDING) {
 85	            throw new OperationNotAllowedException("Cannot confirm reservation in status " + reservation.getStatus());
 86	        }
 87	
