144	    private BigDecimal calculateRefund(Reservation reservation) {
145	        if (reservation.getRatePlan() == RatePlan.NON_REFUNDABLE) {
146	            return BigDecimal.ZERO;
147	        }
148	        return reservation.getAmountPaid();
149	    }
