164	    public String generateDocument(Reservation reservation) {
165	        if (!reservation.isPaid()) {
166	            throw new OperationNotAllowedException("Document is only available for paid reservations");
167	        }
168	
169	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
170	
171	        StringBuilder doc = new StringBuilder();
172	        doc.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
173	        doc.append("Hóspede: ").append(reservation.getGuestName())
174	           .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
175	        doc.append("Quarto: ").append(reservation.getRoomNumber())
176	           .append(" (").append(room.getType()).append(")\n");
177	        doc.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
178	           .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
179	           .append(" | ").append(reservation.getNights())
180	           .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
181	        doc.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
182	
183	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
184	            doc.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
185	        }
186	
187	        doc.append("Total: ").append(formatMoney(reservation.getTotal()));
188	
189	        return doc.toString();
190	    }
