192	    private boolean isRoomAvailable(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeReservationId) {
193	        List<Reservation> conflicting = reservationRepository.findConflicting(roomNumber, checkIn, checkOut);
194	
195	        if (excludeReservationId != null) {
196	            conflicting.removeIf(r -> r.getId().equals(excludeReservationId));
197	        }
198	
199	        return conflicting.isEmpty();
200	    }
