275	        csv.append("reservation,room,check_in,check_out,status,amount\n");
276	
277	        BigDecimal total = BigDecimal.ZERO;
278	
279	        for (Reservation reservation : reservations) {
280	            BigDecimal netAmount = calculateNetAmount(reservation);
281	
282	            if (netAmount.compareTo(BigDecimal.ZERO) > 0) {
283	                csv.append(reservation.getId()).append(",")
284	                   .append(reservation.getRoomNumber()).append(",")
285	                   .append(reservation.getCheckIn()).append(",")
286	                   .append(reservation.getCheckOut()).append(",")
287	                   .append(reservation.getStatus()).append(",")
288	                   .append(formatCsvMoney(netAmount)).append("\n");
289	
290	                total = total.add(netAmount);
291	            }
292	        }
293	
294	        csv.append("total,").append(formatCsvMoney(total));
295	
296	        return csv.toString();
297	    }
