299	    public String generateTourismTaxReport(YearMonth month) {
300	        List<Reservation> reservations = reservationRepository.findByMonth(month);
301	
302	        StringBuilder csv = new StringBuilder();
303	        csv.append(formatTitle("tourism-tax", month.toString())).append("\n");
304	        csv.append("reservation,room,check_in,check_out,guests,nights,tax\n");
305	
306	        BigDecimal total = BigDecimal.ZERO;
307	
308	        for (Reservation reservation : reservations) {
309	            if (isPaidReservation(reservation)) {
310	                BigDecimal tax = calculateTourismTax(reservation);
311	
312	                csv.append(reservation.getId()).append(",")
313	                   .append(reservation.getRoomNumber()).append(",")
314	                   .append(reservation.getCheckIn()).append(",")
315	                   .append(reservation.getCheckOut()).append(",")
316	                   .append(reservation.getGuests()).append(",")
317	                   .append(reservation.getNights()).append(",")
318	                   .append(formatCsvMoney(tax)).append("\n");
319	
320	                total = total.add(tax);
321	            }
322	        }
323	
324	        csv.append("total,").append(formatCsvMoney(total));
325	
326	        return csv.toString();
327	    }
