329	    public String generateRatePlansReport(YearMonth month) {
330	        List<Reservation> reservations = reservationRepository.findByMonth(month);
331	
332	        Map<RatePlan, List<Reservation>> byRatePlan = reservations.stream()
333	            .filter(r -> calculateNetAmount(r).compareTo(BigDecimal.ZERO) > 0)
334	            .collect(Collectors.groupingBy(Reservation::getRatePlan));
335	
336	        StringBuilder csv = new StringBuilder();
337	        csv.append(formatTitle("rate-plans", month.toString())).append("\n");
338	        csv.append("rate_plan,reservations,amount\n");
339	
340	        int totalCount = 0;
341	        BigDecimal totalAmount = BigDecimal.ZERO;
342	
343	        for (RatePlan ratePlan : RatePlan.values()) {
344	            List<Reservation> planReservations = byRatePlan.getOrDefault(ratePlan, List.of());
345	            int count = planReservations.size();
346	            BigDecimal amount = planReservations.stream()
347	                .map(this::calculateNetAmount)
348	                .reduce(BigDecimal.ZERO, BigDecimal::add);
349	
350	            csv.append(ratePlan).append(",")
351	               .append(count).append(",")
352	               .append(formatCsvMoney(amount)).append("\n");
353	
354	            totalCount += count;
355	            totalAmount = totalAmount.add(amount);
356	        }
357	
358	        csv.append("total,").append(totalCount).append(",").append(formatCsvMoney(totalAmount));
359	
360	        return csv.toString();
361	    }
362	
363	    private BigDecimal calculateNetAmount(Reservation reservation) {
364	        BigDecimal paid = reservation.getAmountPaid();
365	        BigDecimal refund = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
366	        return paid.subtract(refund);
367	    }
368	
369	    private boolean isPaidReservation(Reservation reservation) {
370	        return reservation.getStatus() == ReservationStatus.CONFIRMED
371	            || reservation.getStatus() == ReservationStatus.CHECKED_IN
372	            || reservation.getStatus() == ReservationStatus.CHECKED_OUT;
373	    }
374	
375	    private BigDecimal calculateTourismTax(Reservation reservation) {
376	        int guestNights = reservation.getGuests() * reservation.getNights();
377	        return TOURISM_TAX_PER_GUEST_PER_NIGHT.multiply(new BigDecimal(guestNights))
378	            .setScale(2, RoundingMode.HALF_EVEN);
379	    }
380	
381	    private String formatTitle(String reportName, String period) {
382	        return POUSADA_NAME + "," + reportName + "," + period;
383	    }
384	
385	    private String formatCsvMoney(BigDecimal amount) {
386	        return amount.setScale(2, RoundingMode.HALF_EVEN).toString();
387	    }
388	}
