399	public class PricingService {
400	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
401	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
402	
403	    public BigDecimal calculateNightlyRate(Room room, LocalDate date) {
404	        BigDecimal baseRate = room.getNightlyRate();
405	        if (isHighSeason(date)) {
406	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER)
407	                    .setScale(2, RoundingMode.HALF_EVEN);
408	        }
409	        return baseRate;
410	    }
