413	        BigDecimal subtotal = BigDecimal.ZERO;
414	        LocalDate current = checkIn;
415	
416	        while (current.isBefore(checkOut)) {
417	            BigDecimal nightlyRate = calculateNightlyRate(room, current);
418	            subtotal = subtotal.add(nightlyRate);
419	            current = current.plusDays(1);
420	        }
421	
422	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
423	    }
424	
425	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
426	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
427	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT)
428	                    .setScale(2, RoundingMode.HALF_EVEN);
429	        }
430	        return BigDecimal.ZERO;
431	    }
432	
433	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
434	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
435	    }
436	
437	    private boolean isHighSeason(LocalDate date) {
438	        Month month = date.getMonth();
439	        int day = date.getDayOfMonth();
440	
441	        if (month == Month.DECEMBER && day >= 15) {
442	            return true;
443	        }
444	
445	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
446	            return true;
447	        }
448	
449	        if (month == Month.JULY) {
450	            return true;
451	        }
452	
453	        return false;
454	    }
455	}

