  3	import javax.sql.DataSource;
  4	import java.sql.Connection;
  5	import java.sql.SQLException;
  6	import java.sql.Statement;
  7	
  8	public class DatabaseInitializer {
  9	    private final DataSource dataSource;
 10	
 11	    public DatabaseInitializer(DataSource dataSource) {
 12	        this.dataSource = dataSource;
 13	    }
 14	
 15	    public void initialize() {
 16	        try (Connection conn = dataSource.getConnection();
 17	             Statement stmt = conn.createStatement()) {
 18	
 19	            stmt.execute("""
 20	                CREATE TABLE IF NOT EXISTS rooms (
 21	                    number VARCHAR(10) PRIMARY KEY,
 22	                    type VARCHAR(20) NOT NULL,
 23	                    capacity INTEGER NOT NULL,
 24	                    nightly_rate DECIMAL(10, 2) NOT NULL
 25	                )
 26	            """);
 27	
 28	            stmt.execute("""
 29	                CREATE TABLE IF NOT EXISTS reservations (
 30	                    id BIGSERIAL PRIMARY KEY,
 31	                    room_number VARCHAR(10) NOT NULL,
 32	                    guest_name VARCHAR(255) NOT NULL,
 33	                    guest_email VARCHAR(255) NOT NULL,
 34	                    guest_cpf VARCHAR(20) NOT NULL,
 35	                    check_in DATE NOT NULL,
 36	                    check_out DATE NOT NULL,
 37	                    guests INTEGER NOT NULL,
 38	                    rate_plan VARCHAR(20) NOT NULL,
 39	                    nights INTEGER NOT NULL,
 40	                    subtotal DECIMAL(10, 2) NOT NULL,
 41	                    discount DECIMAL(10, 2) NOT NULL,
 42	                    total DECIMAL(10, 2) NOT NULL,
 43	                    status VARCHAR(20) NOT NULL,
 44	                    amount_paid DECIMAL(10, 2) NOT NULL,
 45	                    refund DECIMAL(10, 2),
 46	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
 47	                )
 48	            """);
 49	
 50	            stmt.execute("""
 51	                CREATE TABLE IF NOT EXISTS messages (
 52	                    id BIGSERIAL PRIMARY KEY,
 53	                    channel VARCHAR(20) NOT NULL,
 54	                    recipient VARCHAR(255) NOT NULL,
 55	                    subject VARCHAR(500),
 56	                    body TEXT NOT NULL
 57	                )
 58	            """);
 59	
 60	        } catch (SQLException e) {
 61	            throw new RuntimeException("Failed to initialize database", e);
 62	        }
 63	    }
 64	}
