 69	import javax.sql.DataSource;
 70	import java.sql.*;
 71	import java.util.ArrayList;
 72	import java.util.List;
 73	
 74	public class JdbcMessageRepository implements MessageRepository {
 75	    private final DataSource dataSource;
 76	
 77	    public JdbcMessageRepository(DataSource dataSource) {
 78	        this.dataSource = dataSource;
 79	    }
 80	
 81	    @Override
 82	    public Message save(Message message) {
 83	        String sql = "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?)";
 84	
 85	        try (Connection conn = dataSource.getConnection();
 86	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
 87	
 88	            stmt.setString(1, message.getChannel());
 89	            stmt.setString(2, message.getTo());
 90	            stmt.setString(3, message.getSubject());
 91	            stmt.setString(4, message.getBody());
 92	
 93	            stmt.executeUpdate();
 94	
 95	            try (ResultSet rs = stmt.getGeneratedKeys()) {
 96	                if (rs.next()) {
 97	                    message.setId(rs.getLong(1));
 98	                }
 99	            }
100	        } catch (SQLException e) {
101	            throw new RuntimeException("Failed to save message", e);
102	        }
103	
104	        return message;
105	    }
106	
107	    @Override
108	    public List<Message> findAll() {
109	        String sql = "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id";
110	        List<Message> messages = new ArrayList<>();
111	
112	        try (Connection conn = dataSource.getConnection();
113	             PreparedStatement stmt = conn.prepareStatement(sql);
114	             ResultSet rs = stmt.executeQuery()) {
115	
116	            while (rs.next()) {
117	                Message message = new Message();
118	                message.setId(rs.getLong("id"));
119	                message.setChannel(rs.getString("channel"));
120	                message.setTo(rs.getString("recipient"));
121	                message.setSubject(rs.getString("subject"));
122	                message.setBody(rs.getString("body"));
123	                messages.add(message);
124	            }
125	        } catch (SQLException e) {
126	            throw new RuntimeException("Failed to find messages", e);
127	        }
128	
129	        return messages;
130	    }
131	}
